package com.centrepay.mobile;

import android.app.Activity;
import android.app.AlertDialog;
import android.content.Intent;
import android.net.Uri;
import android.content.res.ColorStateList;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.view.Gravity;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import android.widget.Toast;

import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.util.Calendar;
import java.util.List;
import java.util.Locale;

public class MonthlyReportActivity extends Activity {
    private static final int PRIMARY=Palette.PRIMARY,DARK=Palette.PRIMARY_DARK,TEXT=Palette.TEXT,MUTED=Palette.MUTED,SURFACE=Palette.SURFACE,BORDER=Palette.BORDER;
    private static final int SUCCESS=Palette.SUCCESS,WARNING=Palette.WARNING,ERROR=Palette.ERROR,BLUE=Palette.BLUE;
    private StudentDatabaseHelper database; private LinearLayout content; private Calendar selectedMonth; private MonthlyReport currentReport; private static final int EXPORT_REPORT=41;

    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(DARK);database=new StudentDatabaseHelper(this);selectedMonth=Calendar.getInstance();selectedMonth.set(Calendar.DAY_OF_MONTH,1);LinearLayout root=column();root.setBackgroundColor(Palette.BACKGROUND);root.addView(header(),new LinearLayout.LayoutParams(MATCH,dp(88)));ScrollView scroll=new ScrollView(this);content=column();content.setPadding(dp(12),dp(12),dp(12),dp(28));scroll.addView(content,new ScrollView.LayoutParams(MATCH,WRAP));root.addView(scroll,new LinearLayout.LayoutParams(MATCH,0,1));setContentView(root);}
    @Override protected void onResume(){super.onResume();if(content!=null)render();}

    private void render(){String month=storedMonth();MonthlyReport report=database.getMonthlyReport(month);currentReport=report;content.removeAllViews();content.addView(monthNavigator(),lp(MATCH,WRAP,0,0,0,dp(10)));content.addView(metrics(report),lp(MATCH,WRAP,0,0,0,dp(10)));content.addView(financialOverview(report),lp(MATCH,WRAP,0,0,0,dp(10)));content.addView(paymentStatus(report),lp(MATCH,WRAP,0,0,0,dp(10)));content.addView(teachers(report,month),lp(MATCH,WRAP,0,0,0,dp(10)));content.addView(unpaid(report.unpaidStudents),lp(MATCH,WRAP,0,0,0,dp(10)));content.addView(netCash(report));}

    private View header(){LinearLayout bar=row();bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(16),0,dp(16),0);bar.setBackground(gradient(DARK,PRIMARY,0));ImageView back=icon(R.drawable.ic_arrow_back_24,Color.WHITE);back.setPadding(dp(4),dp(4),dp(4),dp(4));back.setOnClickListener(v->finish());bar.addView(back,new LinearLayout.LayoutParams(dp(40),dp(40)));LinearLayout title=column();title.addView(text("Rapport mensuel",20,Color.WHITE,true));title.addView(text("Vue globale du centre",12,0xffd7efed,false),lp(MATCH,WRAP,0,dp(3),0,0));bar.addView(title,lp(0,WRAP,dp(12),0,0,0,1));bar.addView(text("CentrePay",18,Color.WHITE,true));return bar;}

    private View monthNavigator(){LinearLayout card=card();LinearLayout h=row();h.setGravity(Gravity.CENTER_VERTICAL);h.addView(icon(R.drawable.ic_calendar_month_24,DARK),new LinearLayout.LayoutParams(dp(25),dp(25)));h.addView(text("Période du rapport",14,TEXT,true),lp(0,WRAP,dp(10),0,0,0,1));card.addView(h);LinearLayout controls=row();controls.setGravity(Gravity.CENTER_VERTICAL);TextView month=text(monthLabel()+"  ▾",16,TEXT,true);month.setGravity(Gravity.CENTER_VERTICAL);month.setPadding(dp(14),0,dp(14),0);month.setBackground(round(0xfff8fafc,dp(12),BORDER,dp(1)));month.setOnClickListener(v->showMonthPicker());controls.addView(month,new LinearLayout.LayoutParams(0,dp(50),1));TextView prev=navigation("‹");prev.setOnClickListener(v->{selectedMonth.add(Calendar.MONTH,-1);render();});TextView next=navigation("›");boolean current=isCurrentMonth();next.setEnabled(!current);next.setAlpha(current?.35f:1f);next.setOnClickListener(v->{if(!isCurrentMonth()){selectedMonth.add(Calendar.MONTH,1);render();}});controls.addView(prev,lp(dp(48),dp(48),dp(10),0,dp(6),0));controls.addView(next,new LinearLayout.LayoutParams(dp(48),dp(48)));card.addView(controls,lp(MATCH,WRAP,0,dp(12),0,0));return card;}

    private View metrics(MonthlyReport r){LinearLayout wrap=row();wrap.addView(metric(R.drawable.ic_credit_card_24,"Total encaissé",r.receivedAmount+" DH",PRIMARY,Palette.PRIMARY_SOFT),weighted(1,0,0,dp(4),0));wrap.addView(metric(R.drawable.ic_home_24,"Part centre",r.centerAmount+" DH",BLUE,Palette.BLUE_SOFT),weighted(1,dp(4),0,dp(4),0));wrap.addView(metric(R.drawable.ic_groups_24,"Salaires dus",r.teachersEarnedAmount+" DH",WARNING,0xfffff3d6),weighted(1,dp(4),0,dp(4),0));int unpaidSum=0;for(MonthlyStudentBalance b:r.unpaidStudents)unpaidSum+=b.remainingAmount;wrap.addView(metric(R.drawable.ic_error_24,"Impayés",unpaidSum+" DH",ERROR,Palette.ERROR_SOFT),weighted(1,dp(4),0,0,0));return wrap;}
    private View metric(int res,String label,String value,int color,int bg){LinearLayout m=column();m.setPadding(dp(8),dp(10),dp(8),dp(10));m.setBackground(round(bg,dp(12),0,0));m.addView(icon(res,color),new LinearLayout.LayoutParams(dp(24),dp(24)));m.addView(text(label,11,color,false),lp(MATCH,WRAP,0,dp(8),0,0));m.addView(text(value,14,color,true),lp(MATCH,WRAP,0,dp(4),0,0));return m;}

    private View financialOverview(MonthlyReport r){LinearLayout card=section(R.drawable.ic_analytics_24,"Aperçu financier");int teacher=Math.max(0,r.teachersEarnedAmount),total=Math.max(1,r.centerAmount+teacher),centerPct=Math.round(r.centerAmount*100f/total),teacherPct=100-centerPct;card.addView(text("Répartition des montants",12,MUTED,false),lp(MATCH,WRAP,0,dp(12),0,dp(8)));LinearLayout bar=row();TextView a=text(centerPct+"%",13,Color.WHITE,true);a.setGravity(Gravity.CENTER);a.setBackground(round(PRIMARY,dp(9),0,0));bar.addView(a,new LinearLayout.LayoutParams(0,dp(42),Math.max(1,centerPct)));TextView b=text(teacherPct+"%",13,Color.WHITE,true);b.setGravity(Gravity.CENTER);b.setBackground(round(0xffe0a92f,dp(9),0,0));bar.addView(b,new LinearLayout.LayoutParams(0,dp(42),Math.max(1,teacherPct)));card.addView(bar);LinearLayout labels=row();labels.addView(text("Centre  "+r.centerAmount+" DH",12,DARK,true),new LinearLayout.LayoutParams(0,WRAP,1));TextView prof=text("Professeurs  "+teacher+" DH",12,0xff9a6700,true);prof.setGravity(Gravity.END);labels.addView(prof,new LinearLayout.LayoutParams(0,WRAP,1));card.addView(labels,lp(MATCH,WRAP,0,dp(9),0,0));
        Calendar previous=(Calendar)selectedMonth.clone();previous.add(Calendar.MONTH,-1);String previousKey=String.format(Locale.US,"%04d-%02d",previous.get(Calendar.YEAR),previous.get(Calendar.MONTH)+1);MonthlyReport old=database.getMonthlyReport(previousKey);int change=old.receivedAmount<=0?(r.receivedAmount>0?100:0):Math.round((r.receivedAmount-old.receivedAmount)*100f/old.receivedAmount);TextView comparison=text("Mois précédent : "+old.receivedAmount+" DH     "+(change>=0?"↗ +":"↘ ")+change+"%",11,change>=0?SUCCESS:ERROR,true);comparison.setPadding(dp(10),dp(9),dp(10),dp(9));comparison.setBackground(round(change>=0?0xffe8f7f1:0xffffedef,dp(10),0,0));card.addView(comparison,lp(MATCH,WRAP,0,dp(12),0,0));return card;}

    private View paymentStatus(MonthlyReport r){LinearLayout card=section(R.drawable.ic_description_24,"État des règlements");LinearLayout stats=row();stats.addView(statusBox("✓", "Payés",r.paidCount,SUCCESS,Palette.SUCCESS_SOFT),weighted(1,0,dp(12),dp(5),0));stats.addView(statusBox("◷","Partiels",r.partialCount,WARNING,0xfffff3d6),weighted(1,dp(5),dp(12),dp(5),0));stats.addView(statusBox("!","Impayés",r.unpaidCount,ERROR,Palette.ERROR_SOFT),weighted(1,dp(5),dp(12),0,0));card.addView(stats);return card;}
    private View statusBox(String symbol,String label,int value,int color,int bg){LinearLayout box=row();box.setGravity(Gravity.CENTER_VERTICAL);box.setPadding(dp(9),dp(10),dp(9),dp(10));box.setBackground(round(bg,dp(11),0,0));TextView ico=text(symbol,16,Color.WHITE,true);ico.setGravity(Gravity.CENTER);ico.setBackground(round(color,dp(18),0,0));box.addView(ico,new LinearLayout.LayoutParams(dp(36),dp(36)));LinearLayout copy=column();copy.addView(text(label,11,TEXT,false));copy.addView(text(String.valueOf(value),16,color,true),lp(MATCH,WRAP,0,dp(3),0,0));box.addView(copy,lp(0,WRAP,dp(8),0,0,0,1));return box;}

    private View teachers(MonthlyReport r,String month){LinearLayout card=section(R.drawable.ic_groups_24,"Professeurs");LinearLayout totals=row();totals.addView(smallTotal("Déjà versé",r.teachersPaidAmount,SUCCESS,Palette.PRIMARY_SOFT),weighted(1,0,dp(12),dp(5),0));totals.addView(smallTotal("Reste à verser",Math.max(0,r.teachersEarnedAmount-r.teachersPaidAmount),WARNING,0xfffff3d6),weighted(1,dp(5),dp(12),0,0));card.addView(totals);List<TeacherBalance> balances=database.getTeacherBalances(month);int shown=0;for(TeacherBalance b:balances){if(b.earnedAmount<=0||shown++==3)continue;LinearLayout line=row();line.setGravity(Gravity.CENTER_VERTICAL);line.setPadding(0,dp(5),0,dp(5));line.setOnClickListener(v->{Intent i=new Intent(this,TeacherMonthlySalaryActivity.class);i.putExtra(TeacherMonthlySalaryActivity.EXTRA_TEACHER_ID,b.teacher.id);startActivity(i);});TextView av=text(initials(b.teacher.fullName),10,DARK,true);av.setGravity(Gravity.CENTER);av.setBackground(round(0xffddf7f4,dp(18),0,0));line.addView(av,new LinearLayout.LayoutParams(dp(36),dp(36)));line.addView(text(b.teacher.fullName,11,TEXT,true),lp(0,WRAP,dp(8),0,dp(6),0,1));line.addView(text(b.earnedAmount+" DH",11,TEXT,true));TextView st=text(b.remainingAmount==0?"  ✓ À jour":"  ◷ En cours",10,b.remainingAmount==0?SUCCESS:WARNING,true);line.addView(st,lp(WRAP,WRAP,dp(8),0,0,0));card.addView(line,lp(MATCH,WRAP,0,dp(9),0,0));}return card;}
    private View smallTotal(String label,int value,int color,int bg){LinearLayout v=column();v.setPadding(dp(12),dp(10),dp(12),dp(10));v.setBackground(round(bg,dp(11),0,0));v.addView(text(label,11,MUTED,false));v.addView(text(value+" DH",15,color,true),lp(MATCH,WRAP,0,dp(4),0,0));return v;}

    private View unpaid(List<MonthlyStudentBalance> list){LinearLayout card=section(R.drawable.ic_groups_24,"Élèves en attente");if(list.isEmpty()){TextView good=text("Tous les élèves ont réglé ce mois.",13,SUCCESS,true);good.setPadding(dp(12),dp(16),dp(12),dp(16));good.setBackground(round(Palette.SUCCESS_SOFT,dp(11),0,0));card.addView(good,lp(MATCH,WRAP,0,dp(12),0,0));return card;}int shown=0;for(MonthlyStudentBalance b:list){if(shown++==4)break;LinearLayout line=row();line.setGravity(Gravity.CENTER_VERTICAL);line.setPadding(0,dp(5),0,dp(5));line.setOnClickListener(v->{Intent i=new Intent(this,StudentDetailActivity.class);i.putExtra("student_id",b.studentId);startActivity(i);});TextView av=text(initials(b.studentName),10,DARK,true);av.setGravity(Gravity.CENTER);av.setBackground(round(0xffddf7f4,dp(18),0,0));line.addView(av,new LinearLayout.LayoutParams(dp(36),dp(36)));LinearLayout info=column();info.addView(text(b.studentName,11,TEXT,true));info.addView(text(b.level,11,MUTED,false),lp(MATCH,WRAP,0,dp(2),0,0));line.addView(info,lp(0,WRAP,dp(8),0,dp(6),0,1));line.addView(text(b.remainingAmount+" DH",11,TEXT,true));TextView st=text(b.paidAmount>0?"  Partiel":"  Impayé",10,b.paidAmount>0?WARNING:ERROR,true);line.addView(st,lp(WRAP,WRAP,dp(8),0,0,0));card.addView(line,lp(MATCH,WRAP,0,dp(9),0,0));}return card;}
    private View netCash(MonthlyReport r){LinearLayout card=row();card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(dp(14),dp(14),dp(14),dp(14));card.setBackground(round(r.cashAfterTeacherPayments>=0?Palette.PRIMARY_SOFT:0xffffe8e8,dp(16),0,0));card.addView(icon(R.drawable.ic_credit_card_24,r.cashAfterTeacherPayments>=0?DARK:ERROR),new LinearLayout.LayoutParams(dp(30),dp(30)));LinearLayout copy=column();copy.addView(text("Caisse nette",12,MUTED,false));copy.addView(text(r.cashAfterTeacherPayments+" DH",20,r.cashAfterTeacherPayments>=0?DARK:ERROR,true),lp(MATCH,WRAP,0,dp(3),0,0));card.addView(copy,lp(0,WRAP,dp(12),0,0,0,1));TextView export=text("Exporter CSV",13,Color.WHITE,true);export.setGravity(Gravity.CENTER);export.setBackground(round(PRIMARY,dp(11),0,0));export.setOnClickListener(v->exportReport());card.addView(export,new LinearLayout.LayoutParams(dp(125),dp(46)));return card;}

    private boolean isCurrentMonth(){Calendar now=Calendar.getInstance();return selectedMonth.get(Calendar.YEAR)==now.get(Calendar.YEAR)&&selectedMonth.get(Calendar.MONTH)==now.get(Calendar.MONTH);}
    private void showMonthPicker(){List<String> labels=new java.util.ArrayList<>();List<Calendar> values=new java.util.ArrayList<>();Calendar cursor=Calendar.getInstance();cursor.set(Calendar.DAY_OF_MONTH,1);for(int i=0;i<24;i++){Calendar value=(Calendar)cursor.clone();value.add(Calendar.MONTH,-i);values.add(value);String[] names={"Janvier","Février","Mars","Avril","Mai","Juin","Juillet","Août","Septembre","Octobre","Novembre","Décembre"};labels.add(names[value.get(Calendar.MONTH)]+" "+value.get(Calendar.YEAR));}new AlertDialog.Builder(this).setTitle("Choisir le mois").setItems(labels.toArray(new String[0]),(d,w)->{selectedMonth=values.get(w);render();}).show();}
    private void exportReport(){Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.setType("text/csv");intent.putExtra(Intent.EXTRA_TITLE,"rapport-centrepay-"+storedMonth()+".csv");startActivityForResult(intent,EXPORT_REPORT);}
    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode!=EXPORT_REPORT||resultCode!=RESULT_OK||data==null||data.getData()==null||currentReport==null)return;Uri uri=data.getData();try(OutputStream output=getContentResolver().openOutputStream(uri)){if(output==null)throw new Exception();output.write(csv(currentReport).getBytes(StandardCharsets.UTF_8));Toast.makeText(this,"Rapport exporté.",Toast.LENGTH_LONG).show();}catch(Exception error){Toast.makeText(this,"Impossible d'exporter le rapport.",Toast.LENGTH_LONG).show();}}
    private String csv(MonthlyReport r){StringBuilder c=new StringBuilder("Rapport CentrePay;").append(monthLabel()).append("\n\nIndicateur;Montant DH\nTotal encaissé;").append(r.receivedAmount).append("\nPart centre;").append(r.centerAmount).append("\nSalaires dus;").append(r.teachersEarnedAmount).append("\nSalaires versés;").append(r.teachersPaidAmount).append("\nCaisse nette;").append(r.cashAfterTeacherPayments).append("\n\nStatut;Nombre\nPayés;").append(r.paidCount).append("\nPartiels;").append(r.partialCount).append("\nImpayés;").append(r.unpaidCount).append("\n\nÉlève;Niveau;Dû;Payé;Reste\n");for(MonthlyStudentBalance b:r.unpaidStudents)c.append(csvCell(b.studentName)).append(';').append(csvCell(b.level)).append(';').append(b.totalAmount).append(';').append(b.paidAmount).append(';').append(b.remainingAmount).append('\n');return c.toString();}
    private String csvCell(String value){return "\""+(value==null?"":value.replace("\"","\"\""))+"\"";}

    private LinearLayout card(){LinearLayout v=column();v.setPadding(dp(12),dp(12),dp(12),dp(12));v.setBackground(round(SURFACE,dp(16),BORDER,dp(1)));v.setElevation(dp(1));return v;}private LinearLayout section(int res,String title){LinearLayout card=card();LinearLayout head=row();head.setGravity(Gravity.CENTER_VERTICAL);head.addView(icon(res,DARK),new LinearLayout.LayoutParams(dp(24),dp(24)));head.addView(text(title,15,TEXT,true),lp(0,WRAP,dp(10),0,0,0,1));card.addView(head);return card;}
    private String storedMonth(){return String.format(Locale.US,"%04d-%02d",selectedMonth.get(Calendar.YEAR),selectedMonth.get(Calendar.MONTH)+1);}private String monthLabel(){String[] n={"Janvier","Février","Mars","Avril","Mai","Juin","Juillet","Août","Septembre","Octobre","Novembre","Décembre"};return n[selectedMonth.get(Calendar.MONTH)]+" "+selectedMonth.get(Calendar.YEAR);}private String initials(String n){if(n==null||n.trim().isEmpty())return "--";String[] p=n.trim().split("\\s+");return(p[0].substring(0,1)+(p.length>1?p[p.length-1].substring(0,1):"")).toUpperCase(Locale.ROOT);}
    private TextView navigation(String value){TextView v=text(value,27,DARK,false);v.setGravity(Gravity.CENTER);v.setBackground(round(0xfff1f5f9,dp(12),0,0));return v;}private ImageView icon(int r,int c){ImageView v=new ImageView(this);v.setImageResource(r);v.setImageTintList(ColorStateList.valueOf(c));v.setScaleType(ImageView.ScaleType.CENTER_INSIDE);return v;}private TextView text(String v,int s,int c,boolean b){TextView x=new TextView(this);x.setText(v);x.setTextSize(s);x.setTextColor(c);x.setIncludeFontPadding(false);if(b)x.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return x;}private LinearLayout column(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);return v;}private LinearLayout row(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.HORIZONTAL);return v;}private GradientDrawable round(int c,int r,int s,int w){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(r);if(w>0)d.setStroke(w,s);return d;}private GradientDrawable gradient(int a,int b,int r){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,new int[]{a,b});d.setCornerRadius(r);return d;}private LinearLayout.LayoutParams lp(int w,int h,int l,int t,int r,int b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(w,h);p.setMargins(l,t,r,b);return p;}private LinearLayout.LayoutParams lp(int w,int h,int l,int t,int r,int b,float weight){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(w,h,weight);p.setMargins(l,t,r,b);return p;}private LinearLayout.LayoutParams weighted(float w,int l,int t,int r,int b){return lp(0,WRAP,l,t,r,b,w);}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}private static final int MATCH=ViewGroup.LayoutParams.MATCH_PARENT,WRAP=ViewGroup.LayoutParams.WRAP_CONTENT;
}
